GAD.reg("pyq","o-p6-mtp-may2023-s1",[{"id":"o-p6-mtp-may2023-s1-m1-1","section":"I","no":1,"marks":2,"type":"MCQ","stem":"…………. is the summary of significant matters identified during audit and way they are addressed :","options":["Audit File","Audit Programme","Completion memorandum","Checklists"],"group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c1","label":"Case Scenario 1","context":"M/s SPR & Associates are appointed as auditors of XYZ Ltd. for the Financial Year 2021-22.\n\n- The team consisted of Mr. S, Mr. P, Mr. R all Chartered Accountants and three article assistants.\n- Mr. S, the engagement partner, briefed the audit staff about various items of financial statement to be checked in detail in case of XYZ Ltd and about various aspects to be covered in the audit of the company.\n- Mr. S told the audit staff about audit documentation, audit evidence, audit file, completion memorandum and many other things along with relevant Standards of Auditing applicable.\n- Mr. S also told the staff about the risk of material misstatement that the financial statements are prone to and how it affects the sufficiency and appropriateness of audit evidence.\n- The audit staff was also apprised about the various audit procedures to be adopted while conducting the audit of XYZ Ltd.\n- Further discussions were done about various types of risks related to financial statement and the audit work, the related audit procedures, and the risk assessment procedures.\n- The engagement team is also very particular about the application of various Standards on Auditing applicable in case of XYZ Ltd.\n\nBased on the above facts, answer the following:-"},"answer":{"kind":"single","value":"C"},"key_raw":"C","label":"MCQ 1.1","ord":0,"ans":"**(C)** Completion Memorandum","ours":{"difficulty":"easy"},"pg":{"q":"1","a":"1"},"case":"o-p6-mtp-may2023-s1-c1","tags":["aud.doc.sa230"]},{"id":"o-p6-mtp-may2023-s1-m1-2","section":"I","no":1,"marks":2,"type":"MCQ","stem":"The susceptibility of an assertion to a misstatement that could be material before consideration of any related control is………………:","options":["Control Risk","Inherent Risk","Audit Risk","Significant Risk"],"group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c1","label":"Case Scenario 1","context":"M/s SPR & Associates are appointed as auditors of XYZ Ltd. for the Financial Year 2021-22.\n\n- The team consisted of Mr. S, Mr. P, Mr. R all Chartered Accountants and three article assistants.\n- Mr. S, the engagement partner, briefed the audit staff about various items of financial statement to be checked in detail in case of XYZ Ltd and about various aspects to be covered in the audit of the company.\n- Mr. S told the audit staff about audit documentation, audit evidence, audit file, completion memorandum and many other things along with relevant Standards of Auditing applicable.\n- Mr. S also told the staff about the risk of material misstatement that the financial statements are prone to and how it affects the sufficiency and appropriateness of audit evidence.\n- The audit staff was also apprised about the various audit procedures to be adopted while conducting the audit of XYZ Ltd.\n- Further discussions were done about various types of risks related to financial statement and the audit work, the related audit procedures, and the risk assessment procedures.\n- The engagement team is also very particular about the application of various Standards on Auditing applicable in case of XYZ Ltd.\n\nBased on the above facts, answer the following:-"},"answer":{"kind":"single","value":"B"},"key_raw":"B","label":"MCQ 1.2","ord":1,"ans":"**(B)** Inherent Risk","ours":{"approach":"\"Before consideration of any related control\" is the phrase that separates one component of audit risk from the others.","difficulty":"easy"},"pg":{"q":"1","a":"1"},"case":"o-p6-mtp-may2023-s1-c1","tags":["aud.risk.model"]},{"id":"o-p6-mtp-may2023-s1-m1-3","section":"I","no":1,"marks":2,"type":"MCQ","stem":"Statement 1: Audit procedures consist of Risk Assessments Procedures and other procedures.\n\nStatement 2: Substantive procedures consist of test of details and analytical procedures.","options":["Only Statement 1 is correct","Only Statement 2 is correct","Both 1 & 2 are correct","Both 1 & 2 are incorrect"],"group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c1","label":"Case Scenario 1","context":"M/s SPR & Associates are appointed as auditors of XYZ Ltd. for the Financial Year 2021-22.\n\n- The team consisted of Mr. S, Mr. P, Mr. R all Chartered Accountants and three article assistants.\n- Mr. S, the engagement partner, briefed the audit staff about various items of financial statement to be checked in detail in case of XYZ Ltd and about various aspects to be covered in the audit of the company.\n- Mr. S told the audit staff about audit documentation, audit evidence, audit file, completion memorandum and many other things along with relevant Standards of Auditing applicable.\n- Mr. S also told the staff about the risk of material misstatement that the financial statements are prone to and how it affects the sufficiency and appropriateness of audit evidence.\n- The audit staff was also apprised about the various audit procedures to be adopted while conducting the audit of XYZ Ltd.\n- Further discussions were done about various types of risks related to financial statement and the audit work, the related audit procedures, and the risk assessment procedures.\n- The engagement team is also very particular about the application of various Standards on Auditing applicable in case of XYZ Ltd.\n\nBased on the above facts, answer the following:-"},"answer":{"kind":"single","value":"C"},"key_raw":"C","label":"MCQ 1.3","ord":2,"ans":"**(C)** Both 1 & 2 are correct","ours":{"difficulty":"easy"},"pg":{"q":"2","a":"1","cq":"1"},"case":"o-p6-mtp-may2023-s1-c1","tags":["aud.risk.sa330","aud.evid.sa500"]},{"id":"o-p6-mtp-may2023-s1-m1-4","section":"I","no":1,"marks":2,"type":"MCQ","stem":"…………….. refers to the audit procedures performed to obtain an understanding of the entity and its environment, including the entity’s internal control, to identify and assess the risks of material misstatement, whether due to fraud or error at the financial statement and assertion levels: -","options":["Analytical Procedures","Risk Assessment Procedures","Audit Procedures","Substantive Analytical Procedures"],"group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c1","label":"Case Scenario 1","context":"M/s SPR & Associates are appointed as auditors of XYZ Ltd. for the Financial Year 2021-22.\n\n- The team consisted of Mr. S, Mr. P, Mr. R all Chartered Accountants and three article assistants.\n- Mr. S, the engagement partner, briefed the audit staff about various items of financial statement to be checked in detail in case of XYZ Ltd and about various aspects to be covered in the audit of the company.\n- Mr. S told the audit staff about audit documentation, audit evidence, audit file, completion memorandum and many other things along with relevant Standards of Auditing applicable.\n- Mr. S also told the staff about the risk of material misstatement that the financial statements are prone to and how it affects the sufficiency and appropriateness of audit evidence.\n- The audit staff was also apprised about the various audit procedures to be adopted while conducting the audit of XYZ Ltd.\n- Further discussions were done about various types of risks related to financial statement and the audit work, the related audit procedures, and the risk assessment procedures.\n- The engagement team is also very particular about the application of various Standards on Auditing applicable in case of XYZ Ltd.\n\nBased on the above facts, answer the following:-"},"answer":{"kind":"single","value":"B"},"key_raw":"B","label":"MCQ 1.4","ord":3,"ans":"**(B)** Risk Assessment Procedures","ours":{"difficulty":"easy"},"pg":{"q":"2","a":"1","cq":"1"},"case":"o-p6-mtp-may2023-s1-c1","tags":["aud.risk.sa315"]},{"id":"o-p6-mtp-may2023-s1-m1-5","section":"I","no":1,"marks":2,"type":"MCQ","stem":"Statement 1:- Substantive Procedures alone can provide sufficient and appropriate audit evidence at the assertion level.\n\nStatement 2:-Test of Control is audit procedure designed to evaluate the operating effectiveness of controls in prevention, detection and correcting material misstatement at the assertion level.","options":["Only Statement 1 is correct","Only Statement 2 is correct","Both 1 & 2 are correct","Both 1 & 2 are incorrect"],"group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c1","label":"Case Scenario 1","context":"M/s SPR & Associates are appointed as auditors of XYZ Ltd. for the Financial Year 2021-22.\n\n- The team consisted of Mr. S, Mr. P, Mr. R all Chartered Accountants and three article assistants.\n- Mr. S, the engagement partner, briefed the audit staff about various items of financial statement to be checked in detail in case of XYZ Ltd and about various aspects to be covered in the audit of the company.\n- Mr. S told the audit staff about audit documentation, audit evidence, audit file, completion memorandum and many other things along with relevant Standards of Auditing applicable.\n- Mr. S also told the staff about the risk of material misstatement that the financial statements are prone to and how it affects the sufficiency and appropriateness of audit evidence.\n- The audit staff was also apprised about the various audit procedures to be adopted while conducting the audit of XYZ Ltd.\n- Further discussions were done about various types of risks related to financial statement and the audit work, the related audit procedures, and the risk assessment procedures.\n- The engagement team is also very particular about the application of various Standards on Auditing applicable in case of XYZ Ltd.\n\nBased on the above facts, answer the following:-"},"answer":{"kind":"single","value":"B"},"key_raw":"B","label":"MCQ 1.5","ord":4,"ans":"**(B)** Only Statement 2 is correct","ours":{"approach":"Ask whether SA 330 lets substantive procedures alone always suffice, or whether some risks can only be answered by testing controls.","difficulty":"medium"},"pg":{"q":"2","a":"1","cq":"1"},"case":"o-p6-mtp-may2023-s1-c1","tags":["aud.risk.sa330"]},{"id":"o-p6-mtp-may2023-s1-m2-1","section":"I","no":2,"marks":2,"type":"MCQ","stem":"Statement 1: Although Written Representations provide necessary audit evidence, they do not provide sufficient and appropriate audit evidence on their own about the matters with which they deal.\n\nStatement 2: Written Representations do not include financial statements, the assertions within, or supporting books and records.","options":["Only Statement 1 is correct","Only Statement 2 is correct","Both Statement 1 & 2 are correct","None of Statement 1 & 2 is correct"],"group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c2","label":"Case Scenario 2","context":"M/s ABC & Associates have been appointed as auditors of Venus Ltd. for the Financial Year 2020-21.\n\n- During the course of audit, the auditors notice that certain legal expenses been charged to revenue during the financial year by Venus Ltd.\n- These legal expenses are related to litigations going against the company regarding its Corporate Social Responsibility expenses incurred near its factory area.\n- Further, M/s ABC & Associates noticed that there is a major change in the debtors and creditors account of Venus Ltd. during the financial year under audit. The auditors have decided to send balance confirmation requests to the debtors and creditors of Venus Ltd. Also, the auditors decide to take management representation letters wherever required.\n- The auditors have noticed certain related party transactions reflected in the financial statements of Venus Ltd. during the financial year under audit. The transaction is between Venus Ltd. and a Company owned by wife of one of the directors of Venus Ltd.\n- The auditors have become aware of certain subsequent events occurring in case of Venus Ltd. These are related to the outcomes of the litigations going against Venus Ltd.\n- The auditors are also concerned whether the litigations going against Venus Ltd. and their outcomes have any impact on the going concern of the company.\n\nBased on the above facts, answer the following:-"},"answer":{"kind":"single","value":"C"},"key_raw":"C","label":"MCQ 2.1","ord":5,"ans":"**(C)** Both Statement 1 & 2 are correct","ours":{"difficulty":"easy"},"pg":{"q":"2-3","a":"1","cq":"2"},"case":"o-p6-mtp-may2023-s1-c2","tags":["aud.complete.sa580"]},{"id":"o-p6-mtp-may2023-s1-m2-2","section":"I","no":2,"marks":2,"type":"MCQ","stem":"The auditor can perform the following procedures to identify litigation and claims of Venus Ltd.:-\n\n(i) Inquiry of management including in house legal counsel.\n\n(ii) Reviewing legal expenses account.\n\n(iii) Reviewing of minutes of meetings of those charged to governance and correspondence between entity and external legal counsel.","options":["(i) & (i) are correct","(i), (ii) & (iii) are correct","(ii) & (iii) are correct","only (i) is correct"],"group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c2","label":"Case Scenario 2","context":"M/s ABC & Associates have been appointed as auditors of Venus Ltd. for the Financial Year 2020-21.\n\n- During the course of audit, the auditors notice that certain legal expenses been charged to revenue during the financial year by Venus Ltd.\n- These legal expenses are related to litigations going against the company regarding its Corporate Social Responsibility expenses incurred near its factory area.\n- Further, M/s ABC & Associates noticed that there is a major change in the debtors and creditors account of Venus Ltd. during the financial year under audit. The auditors have decided to send balance confirmation requests to the debtors and creditors of Venus Ltd. Also, the auditors decide to take management representation letters wherever required.\n- The auditors have noticed certain related party transactions reflected in the financial statements of Venus Ltd. during the financial year under audit. The transaction is between Venus Ltd. and a Company owned by wife of one of the directors of Venus Ltd.\n- The auditors have become aware of certain subsequent events occurring in case of Venus Ltd. These are related to the outcomes of the litigations going against Venus Ltd.\n- The auditors are also concerned whether the litigations going against Venus Ltd. and their outcomes have any impact on the going concern of the company.\n\nBased on the above facts, answer the following:-"},"answer":{"kind":"single","value":"B"},"key_raw":"B","label":"MCQ 2.2","ord":6,"ans":"**(B)** (i), (ii) & (iii) are correct","ours":{"approach":"Recall the procedures SA 501 lists for identifying litigation and claims, and check each of the three against that list.","difficulty":"easy"},"pg":{"q":"3","a":"1","cq":"2"},"case":"o-p6-mtp-may2023-s1-c2","tags":["aud.evid.sa501"]},{"id":"o-p6-mtp-may2023-s1-m2-3","section":"I","no":2,"marks":2,"type":"MCQ","stem":"Negative confirmation requests require the third party to respond in the following cases : -","options":["If there is agreement","If there is disagreement","In both cases of agreement as well as disagreement","None of the above."],"group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c2","label":"Case Scenario 2","context":"M/s ABC & Associates have been appointed as auditors of Venus Ltd. for the Financial Year 2020-21.\n\n- During the course of audit, the auditors notice that certain legal expenses been charged to revenue during the financial year by Venus Ltd.\n- These legal expenses are related to litigations going against the company regarding its Corporate Social Responsibility expenses incurred near its factory area.\n- Further, M/s ABC & Associates noticed that there is a major change in the debtors and creditors account of Venus Ltd. during the financial year under audit. The auditors have decided to send balance confirmation requests to the debtors and creditors of Venus Ltd. Also, the auditors decide to take management representation letters wherever required.\n- The auditors have noticed certain related party transactions reflected in the financial statements of Venus Ltd. during the financial year under audit. The transaction is between Venus Ltd. and a Company owned by wife of one of the directors of Venus Ltd.\n- The auditors have become aware of certain subsequent events occurring in case of Venus Ltd. These are related to the outcomes of the litigations going against Venus Ltd.\n- The auditors are also concerned whether the litigations going against Venus Ltd. and their outcomes have any impact on the going concern of the company.\n\nBased on the above facts, answer the following:-"},"answer":{"kind":"single","value":"B"},"key_raw":"B","label":"MCQ 2.3","ord":7,"ans":"**(B)** If there is disagreement","ours":{"difficulty":"easy"},"pg":{"q":"3","a":"1","cq":"2"},"case":"o-p6-mtp-may2023-s1-c2","tags":["aud.evid.sa505"]},{"id":"o-p6-mtp-may2023-s1-m2-4","section":"I","no":2,"marks":2,"type":"MCQ","stem":"Statement 1:- A failure of the confirming party to respond, or fully respond to a positive confirmation request or a confirmation request returned undelivered is a case of Non Response.\n\nStatement 2:- A response that indicates difference between information requested to be confirmed and contained in entity’s records and information provided by the confirming part is a case of Exception.","options":["Only Statement 1 is correct","Only Statement 2 is correct","Both Statement 1 & 2 are correct","None of Statement 1 & 2 is correct"],"group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c2","label":"Case Scenario 2","context":"M/s ABC & Associates have been appointed as auditors of Venus Ltd. for the Financial Year 2020-21.\n\n- During the course of audit, the auditors notice that certain legal expenses been charged to revenue during the financial year by Venus Ltd.\n- These legal expenses are related to litigations going against the company regarding its Corporate Social Responsibility expenses incurred near its factory area.\n- Further, M/s ABC & Associates noticed that there is a major change in the debtors and creditors account of Venus Ltd. during the financial year under audit. The auditors have decided to send balance confirmation requests to the debtors and creditors of Venus Ltd. Also, the auditors decide to take management representation letters wherever required.\n- The auditors have noticed certain related party transactions reflected in the financial statements of Venus Ltd. during the financial year under audit. The transaction is between Venus Ltd. and a Company owned by wife of one of the directors of Venus Ltd.\n- The auditors have become aware of certain subsequent events occurring in case of Venus Ltd. These are related to the outcomes of the litigations going against Venus Ltd.\n- The auditors are also concerned whether the litigations going against Venus Ltd. and their outcomes have any impact on the going concern of the company.\n\nBased on the above facts, answer the following:-"},"answer":{"kind":"single","value":"C"},"key_raw":"C","label":"MCQ 2.4","ord":8,"ans":"**(C)** Both Statement 1 & 2 are correct","ours":{"difficulty":"easy"},"pg":{"q":"3","a":"1","cq":"2"},"case":"o-p6-mtp-may2023-s1-c2","tags":["aud.evid.sa505"]},{"id":"o-p6-mtp-may2023-s1-m2-5","section":"I","no":2,"marks":2,"type":"MCQ","stem":"Which of the following is correct so far as the related party transactions are concerned: -\n\n(i) Many related party transactions are in the normal course of business.\n\n(ii) Related party transactions may not be conducted under normal market term and conditions.\n\n(iii) In some circumstances, related party transactions may give rise to higher risks of material misstatement.","options":["only (i) is correct","(i) & (iii) are correct","(i), (ii) & (iii) are correct","(i) and (ii) are correct"],"group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c2","label":"Case Scenario 2","context":"M/s ABC & Associates have been appointed as auditors of Venus Ltd. for the Financial Year 2020-21.\n\n- During the course of audit, the auditors notice that certain legal expenses been charged to revenue during the financial year by Venus Ltd.\n- These legal expenses are related to litigations going against the company regarding its Corporate Social Responsibility expenses incurred near its factory area.\n- Further, M/s ABC & Associates noticed that there is a major change in the debtors and creditors account of Venus Ltd. during the financial year under audit. The auditors have decided to send balance confirmation requests to the debtors and creditors of Venus Ltd. Also, the auditors decide to take management representation letters wherever required.\n- The auditors have noticed certain related party transactions reflected in the financial statements of Venus Ltd. during the financial year under audit. The transaction is between Venus Ltd. and a Company owned by wife of one of the directors of Venus Ltd.\n- The auditors have become aware of certain subsequent events occurring in case of Venus Ltd. These are related to the outcomes of the litigations going against Venus Ltd.\n- The auditors are also concerned whether the litigations going against Venus Ltd. and their outcomes have any impact on the going concern of the company.\n\nBased on the above facts, answer the following:-"},"answer":{"kind":"single","value":"C"},"key_raw":"C","label":"MCQ 2.5","ord":9,"ans":"**(C)** (i), (ii) & (iii) are correct","ours":{"difficulty":"easy"},"pg":{"q":"3","a":"1","cq":"2"},"case":"o-p6-mtp-may2023-s1-c2","tags":["aud.evid.sa550"]},{"id":"o-p6-mtp-may2023-s1-m1","section":"I","no":1,"marks":1,"type":"MCQ","stem":"The overall audit strategy and the audit plan remain the _______ responsibility","options":["auditor’s","management’s","those charged with governance.","both management and those charged with governance."],"answer":{"kind":"single","value":"A"},"key_raw":"A","label":"General MCQ 1","ord":10,"ans":"**(A)**","ours":{"difficulty":"easy"},"pg":{"q":"4","a":"1"},"tags":["aud.plan.sa300"]},{"id":"o-p6-mtp-may2023-s1-m2","section":"I","no":2,"marks":1,"type":"MCQ","stem":"CA Amar is the statutory auditor of XYZ Ltd. for the FY 2020-21. During the process of assembling the audit file, CA Amar briefed his team as to what all changes can be made to the audit documentation at that stage. Which of the following changes cannot be made to the audit documentation during the final assembly process?","options":["Sorting, collating & cross referencing of working papers.","Signing off completion checklists relating to the file assembly process.","Deleting or discarding superseded documents.","Recalculation of Depreciation."],"answer":{"kind":"single","value":"D"},"key_raw":"D","label":"General MCQ 2","ord":11,"ans":"**(D)**","ours":{"approach":"Assembly of the final file is administrative: separate the clerical changes from anything that would be new audit work.","difficulty":"medium"},"pg":{"q":"4","a":"1"},"tags":["aud.doc.sa230"]},{"id":"o-p6-mtp-may2023-s1-m3","section":"I","no":3,"marks":1,"type":"MCQ","stem":"The auditor has no obligation to perform any audit procedures regarding the financial statements after the date of the auditor’s report. However, when, after the date of the auditor’s report but before the date the financial statements are issued, a fact becomes known to the auditor that, had it been known to the auditor at the date of the auditor’s report, may have caused the auditor to amend the auditor’s report, the auditor shall:","options":["Discuss the matter with management and, where appropriate, those charged with governance.","Determine whether the financial statements need amendment.","Inquire how management intends to address the matter in the financial statements.","All of the above"],"answer":{"kind":"single","value":"D"},"key_raw":"D","label":"General MCQ 3","ord":12,"ans":"**(D)**","ours":{"difficulty":"easy"},"pg":{"q":"4","a":"1"},"tags":["aud.complete.sa560"]},{"id":"o-p6-mtp-may2023-s1-m4","section":"I","no":4,"marks":1,"type":"MCQ","stem":"Which of the following is incorrect-\n\nFor the purpose of Identifying and assessing the risks of material misstatement, the auditor shall :","options":["Identify risks throughout the process of obtaining an understanding of the entity and its environment, including relevant controls that relate to the risks, and by considering the classes of transactions, account balances, and disclosures in the financial statements;","Assess the identified risks, and evaluate whether they relate more pervasively to the financial statements as a whole and potentially affect many assertions;","Relate the identified risks to what can go wrong at the assertion level, taking account of relevant controls that the auditor intends to test; and","Not consider the likelihood of misstatement, including the possibility of multiple misstatements, and whether the potential misstatement is of a magnitude that could result in a material misstatement."],"answer":{"kind":"single","value":"D"},"key_raw":"D","label":"General MCQ 4","ord":13,"ans":"**(D)**","ours":{"difficulty":"medium"},"pg":{"q":"4","a":"1"},"tags":["aud.risk.sa315"]},{"id":"o-p6-mtp-may2023-s1-m5","section":"I","no":5,"marks":1,"type":"MCQ","stem":"Which of the following is Incorrect:","options":["An auditor conducting an audit in accordance with SAs is responsible for obtaining absolute assurance that the financial statements taken as a whole are free from material misstatement, whether caused by fraud or error.","As described in SA 200, owing to the inherent limitations of an audit, there is an unavoidable risk that some material misstatements of the financial statements will not be detected, even though the audit is properly planned and performed in accordance with the SAs.","The risk of not detecting a material misstatement resulting from fraud is higher than the risk of not detecting one resulting from error.","The risk of the auditor not detecting a material misstatement resulting from management fraud is greater than for employee fraud."],"answer":{"kind":"single","value":"A"},"key_raw":"A","label":"General MCQ 5","ord":14,"ans":"**(A)**","ours":{"difficulty":"medium"},"pg":{"q":"4-5","a":"1"},"tags":["aud.nature.sa200","aud.nature.limits"]},{"id":"o-p6-mtp-may2023-s1-m6","section":"I","no":6,"marks":1,"type":"MCQ","stem":"Any casual vacancy in the office of a Cost Auditor, whether due to resignation, death or removal, shall be filled by the Board of Directors within ______ days of occurrence of such vacancy and the company shall inform the central government in Form CRA-2 within 30 days of such appointment of cost auditor.","options":["30 Days","45 Days","60 Days","90 Days"],"answer":{"kind":"single","value":"A"},"key_raw":"A","label":"General MCQ 6","ord":15,"ans":"**(A)**","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"1"},"oos":true,"note":"Out of syllabus (old scheme, ours): filling a casual vacancy in the office of a cost auditor (Companies (Cost Records and Audit) Rules, 2014, Form CRA-2) belonged to old Paper 6's company audit content on cost audit; the new-scheme Paper 5 syllabus and the January 2027 Study Material do not cover cost audit (the SM's only casual vacancy is an LLP auditor's), so the item is flagged and carries no tag."},{"id":"o-p6-mtp-may2023-s1-m7","section":"I","no":7,"marks":1,"type":"MCQ","stem":"______________refers to the record of audit procedures performed, relevant audit evidence obtained, and conclusions the auditor reached.","options":["Audit Techniques","Audit evidence","Audit Documentation","Audit Procedures record"],"answer":{"kind":"single","value":"C"},"key_raw":"C","label":"General MCQ 7","ord":16,"ans":"**(C)**","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"1"},"tags":["aud.doc.sa230"]},{"id":"o-p6-mtp-may2023-s1-m8","section":"I","no":8,"marks":1,"type":"MCQ","stem":"In case of Frauds involving amount less than INR 1 crores , the auditor should report to the :-","options":["Central Government","Reserve Bank of India","Bank’s Board/Audit Committee","Comptroller & Audit General"],"answer":{"kind":"single","value":"C"},"key_raw":"C","label":"General MCQ 8","ord":17,"ans":"**(C)**","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"1"},"note":"Ours: the January 2027 Study Material teaches reporting of frauds under section 143(12) read with Rule 13 (below ₹ 1 crore to the audit committee or the Board) in the Audit Report chapter, and repeats it for bank auditors in Audit of Banks; tagged there, not flagged.","tags":["aud.report.companies","aud.bank.auditor"]},{"id":"o-p6-mtp-may2023-s1-m9","section":"I","no":9,"marks":1,"type":"MCQ","stem":"Mrs. Reema has availed a Personal Loan for her Boutique of INR 5 lakhs and a Vehicle Loan to purchase an Activa Scooter for INR 60,000. She is regular in depositing EMI of the Activa Loan but has not made any payments towards the Personal Loan due to low business during the year. In this case, which of the following facilities should be categorized as NPA ?","options":["Activa Loan","Personal Loan","Higher of the two","Both the Activa Loan & the Personal Loan"],"answer":{"kind":"single","value":"D"},"key_raw":"D","label":"General MCQ 9","ord":18,"ans":"**(D)**","ours":{"approach":"Decide whether RBI's asset classification is done facility by facility or borrower by borrower.","difficulty":"medium"},"pg":{"q":"5","a":"1"},"tags":["aud.bank.advances"]},{"id":"o-p6-mtp-may2023-s1-m10","section":"I","no":10,"marks":1,"type":"MCQ","stem":"After a Government expenditure has been incurred and the accounts are closed, the Appropriation Accounts are prepared which are scrutinised by the","options":["CAG","President","Public Accounts Committee","Parliament"],"answer":{"kind":"single","value":"C"},"key_raw":"C","label":"General MCQ 10","ord":19,"ans":"**(C)**","ours":{"difficulty":"easy"},"pg":{"q":"5","a":"1"},"tags":["aud.entities.govt"]},{"id":"o-p6-mtp-may2023-s1-q1i","section":"II","no":1,"marks":2,"type":"DESC","stem":"Advocacy threat, is the threat which occur when an auditing firm, its partner or associate could benefit from a financial interest in an audit client.","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c3","label":"Question 1","context":"Examine with reasons (in short) whether the following statements are correct or incorrect : (Attempt any **7** out of **8**)"},"label":"Q1(i)","part":"(i)","ord":20,"ans":"**Incorrect:** Self-interest threat is the threat which occur when an auditing firm, its partner or associate could benefit from a financial interest in an audit client. Further, Advocacy threat is the threat which occur when the auditor promotes, or is perceived to promote, a client’s opinion to a point where people may believe that objectivity is getting compromised, e.g. when an auditor deals with shares or securities of the audited company, or becomes the client’s advocate in litigation and third party disputes.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"1-2"},"case":"o-p6-mtp-may2023-s1-c3","tags":["aud.ethics.independence"]},{"id":"o-p6-mtp-may2023-s1-q1ii","section":"II","no":1,"marks":2,"type":"DESC","stem":"According to ‘Audit of sanctions’, the auditors try to bring out cases of improper, avoidable, or infructuous expenditure even though the expenditure has been incurred in conformity with the existing rules and regulations.","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c3","label":"Question 1","context":"Examine with reasons (in short) whether the following statements are correct or incorrect : (Attempt any **7** out of **8**)"},"label":"Q1(ii)","part":"(ii)","ord":21,"ans":"**Incorrect.** According to ‘propriety audit’, the auditors try to bring out cases of improper, avoidable, or infructuous expenditure even though the expenditure has been incurred in conformity with the existing rules and regulations. According to 'Audit of sanctions', the auditor has to ensure that each item of expenditure is covered by a sanction, either general or special, of the competent authority.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"2","ca":"1-2"},"case":"o-p6-mtp-may2023-s1-c3","tags":["aud.entities.govt"]},{"id":"o-p6-mtp-may2023-s1-q1iii","section":"II","no":1,"marks":2,"type":"DESC","stem":"Understanding the Internal Control of a company will not help the auditor in developing an Audit Programme.","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c3","label":"Question 1","context":"Examine with reasons (in short) whether the following statements are correct or incorrect : (Attempt any **7** out of **8**)"},"label":"Q1(iii)","part":"(iii)","ord":22,"ans":"**Incorrect:** Understanding the Internal Control of a company will help in developing an Audit Programme because it will assist the auditor and his team to understand as to how much they can rely on internal control of the company and what audit procedures would be appropriate to be used during the course of audit.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"2","ca":"1-2"},"case":"o-p6-mtp-may2023-s1-c3","tags":["aud.plan.program","aud.risk.ic"]},{"id":"o-p6-mtp-may2023-s1-q1iv","section":"II","no":1,"marks":2,"type":"DESC","stem":"Assertions refer to the representations by the auditor to consider the different types of the potential misstatements that may occur.","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c3","label":"Question 1","context":"Examine with reasons (in short) whether the following statements are correct or incorrect : (Attempt any **7** out of **8**)"},"label":"Q1(iv)","part":"(iv)","ord":23,"ans":"**Incorrect:** Assertions refer to representations by management that are embodied in the financial statements as used by the auditor to consider the different types of the potential misstatements that may occur.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"2","ca":"1-2"},"case":"o-p6-mtp-may2023-s1-c3","tags":["aud.evid.assertions"]},{"id":"o-p6-mtp-may2023-s1-q1v","section":"II","no":1,"marks":2,"type":"DESC","stem":"Low acceptable sampling risk requires larger sample size.","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c3","label":"Question 1","context":"Examine with reasons (in short) whether the following statements are correct or incorrect : (Attempt any **7** out of **8**)"},"label":"Q1(v)","part":"(v)","ord":24,"ans":"**Correct:** Sampling risk arises from possibility that the auditor’s conclusion based upon sample may be different from conclusion that would have been reached if same audit procedures were applied on the entire population. If acceptable sampling risk is low, large sample size is needed.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"2","ca":"1-2"},"case":"o-p6-mtp-may2023-s1-c3","tags":["aud.evid.sa530"]},{"id":"o-p6-mtp-may2023-s1-q1vi","section":"II","no":1,"marks":2,"type":"DESC","stem":"The purpose of an audit is to enhance the degree of confidence of intended users in the financial statements.","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c3","label":"Question 1","context":"Examine with reasons (in short) whether the following statements are correct or incorrect : (Attempt any **7** out of **8**)"},"label":"Q1(vi)","part":"(vi)","ord":25,"ans":"**Correct:** As per SA 200 “Overall Objectives of the Independent Auditor and the Conduct of an Audit in Accordance with Standards on Auditing”, the purpose of an audit is to enhance the degree of confidence of intended users in the financial statements. This is achieved by the expression of an opinion by the auditor on whether the financial statements are prepared, in all material respects, in accordance with an applicable financial reporting framework.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"2","ca":"1-2"},"case":"o-p6-mtp-may2023-s1-c3","tags":["aud.nature.sa200"]},{"id":"o-p6-mtp-may2023-s1-q1vii","section":"II","no":1,"marks":2,"type":"DESC","stem":"Narrative record is a series of instructions and/or questions which a member of the auditing staff must follow and/or answer.","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c3","label":"Question 1","context":"Examine with reasons (in short) whether the following statements are correct or incorrect : (Attempt any **7** out of **8**)"},"label":"Q1(vii)","part":"(vii)","ord":26,"ans":"**Incorrect:** Check list is a series of instructions and/or questions which a member of the auditing staff must follow and/or answer. Narrative record is a complete and exhaustive description of the system as found in operation by the auditor.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"2","ca":"1-2"},"case":"o-p6-mtp-may2023-s1-c3","tags":["aud.risk.ic"]},{"id":"o-p6-mtp-may2023-s1-q1viii","section":"II","no":1,"marks":2,"type":"DESC","stem":"Planning is a discrete phase of an audit.","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c3","label":"Question 1","context":"Examine with reasons (in short) whether the following statements are correct or incorrect : (Attempt any **7** out of **8**)"},"label":"Q1(viii)","part":"(viii)","ord":27,"ans":"**Incorrect.** Planning is not a discrete phase of an audit, but rather a continual and iterative process that often begin shortly after (or in connection with) the completion of the previous audit and continues until the completion of the current audit engagement. Planning, however, includes consideration of the timing of certain activities and audit procedures that need to be completed prior to the performance of further audit procedures","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"2","ca":"1-2"},"case":"o-p6-mtp-may2023-s1-c3","tags":["aud.plan.sa300"]},{"id":"o-p6-mtp-may2023-s1-q2a","section":"II","no":2,"marks":4,"type":"DESC","stem":"The firm should establish **policies and procedures** designed to provide it with reasonable assurance that engagements are performed in accordance with professional standards and regulatory and legal requirements, and that the firm or the engagement partner issues reports that are appropriate in the circumstances. Explain.","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c4","label":"Question 2","context":"Discuss the following:"},"label":"Q2(a)","part":"(a)","ord":28,"ans":"The firm should establish policies and procedures designed to provide it with reasonable assurance that engagements are performed in accordance with professional standards and regulatory and legal requirements, and that the firm or the engagement partner issues reports that are appropriate in the circumstances.\n\nThrough its policies and procedures, the firm seeks to establish consistency in the quality of engagement performance. This is often accomplished through written or electronic manuals, software tools or other forms of standardized documentation, and industry or subject matter-specific guidance materials. Matters addressed include the following:\n\n- How engagement teams are briefed on the engagement to obtain an understanding of the objectives of their work.\n- Processes for complying with applicable engagement standards.\n- Processes of engagement supervision, staff training and coaching.\n- Methods of reviewing the work performed, the significant judgments made and the form of report being issued.\n- Appropriate documentation of the work performed and of the timing and extent of the review.\n- Processes to keep all policies and procedures current.","ours":{"approach":"This is SQC 1's element on engagement performance: list the matters the firm's manuals and procedures address, from briefing the team to keeping the policies current.","difficulty":"medium"},"pg":{"q":"6","a":"2"},"case":"o-p6-mtp-may2023-s1-c4","tags":["aud.ethics.qc"]},{"id":"o-p6-mtp-may2023-s1-q2b","section":"II","no":2,"marks":4,"type":"DESC","stem":"Planning an audit involves establishing the overall audit strategy for the engagement and developing an audit plan. Adequate planning benefits the audit of financial statements in several ways. Explain such benefits of planning in the audit of financial statements.","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c4","label":"Question 2","context":"Discuss the following:"},"label":"Q2(b)","part":"(b)","ord":29,"ans":"Planning an audit involves establishing the overall audit strategy for the engagement and developing an audit plan. Adequate planning benefits the audit of financial statements in several ways, including the following:\n\n(a) Helping the auditor to devote appropriate attention to important areas of the audit.\n\n(b) Helping the auditor identify and resolve potential problems on a timely basis.\n\n(c) Helping the auditor properly organize and manage the audit engagement so that it is performed in an effective and efficient manner.\n\n(d) Assisting in the selection of engagement team members with appropriate levels of capabilities and competence to respond to anticipated risks, and the proper assignment of work to them.\n\n(e) Facilitating the direction and supervision of engagement team members and the review of their work.\n\n(f) Assisting, where applicable, in coordination of work done by auditors of components and experts.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"3"},"case":"o-p6-mtp-may2023-s1-c4","tags":["aud.plan.sa300"]},{"id":"o-p6-mtp-may2023-s1-q2c","section":"II","no":2,"marks":3,"type":"DESC","stem":"The division of internal control into five components provides a useful framework for auditors to consider how different aspects of an entity's internal control may affect the audit. Mention those components of internal control.","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c4","label":"Question 2","context":"Discuss the following:"},"label":"Q2(c)","part":"(c)","ord":30,"ans":"**Division of Internal Control into Components:** The division of internal control into the following five components provides a useful framework for auditors to consider how different aspects of an entity’s internal control may affect the audit:\n\n(i) The control environment;\n\n(ii) The entity’s risk assessment process;\n\n(iii) Monitoring of controls.\n\n(iv) Control activities; and\n\n(v) The information system, including the related business processes, relevant to financial reporting, and communication.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"3"},"case":"o-p6-mtp-may2023-s1-c4","tags":["aud.risk.ic"]},{"id":"o-p6-mtp-may2023-s1-q2d","section":"II","no":2,"marks":3,"type":"DESC","stem":"With respect to audit in an automated environment, explain the following:\n\n(i) General (IT) Controls\n\n(ii) Material Weakness\n\n(iii) Data Processing","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c4","label":"Question 2","context":"Discuss the following:"},"label":"Q2(d)","part":"(d)","ord":31,"ans":"(i) General (IT) Controls: Are a type of internal controls that help in mitigating risks that arise due to use of information technology and information systems in a business.\n\n(ii) Material Weakness: A control deficiency or a combination of deficiencies in internal controls that is important enough to merit the attention of those charged with governance since there is a reasonable possibility that a material misstatement will not be prevented or detected in a timely manner by management.\n\n(iii) Data processing: Refers to the systematic recording, storage, retrieval, modification and transformation of electronic data using information systems.","ours":{"difficulty":"medium"},"pg":{"q":"6","a":"3"},"case":"o-p6-mtp-may2023-s1-c4","tags":["aud.risk.it"]},{"id":"o-p6-mtp-may2023-s1-q3a","section":"II","no":3,"marks":4,"type":"DESC","stem":"When auditor identifies deficiencies and report on internal controls, he determines the significant financial statement assertions that are affected by the ineffective controls in order to evaluate the effect on control risk assessments and strategy for the audit of the financial statements. Explain.","label":"Q3(a)","part":"(a)","ord":32,"ans":"**Control risk assessment when control deficiencies are identified:** When auditor identifies deficiencies and report on internal controls, he determines the significant financial statement assertions that are affected by the ineffective controls in order to evaluate the effect on control risk assessments and strategy for the audit of the financial statements.\n\nWhen control deficiencies are identified and auditor identifies and tests more than one control for each relevant assertion, he evaluates control risk considering all of the controls he has tested. If auditor determines that they support a ‘rely on controls’ risk assessment, or if compensating controls are identified, tested and evaluated to be effective, he may conclude that the ‘rely on controls’ is still appropriate. Otherwise we change our control risk assessment to ‘not rely on controls.’\n\nWhen a deficiency relates to an ineffective control that is the only control identified for an assertion, he revises risk assessment to ‘not rely on controls’ for associated assertions, as no other controls have been identified that mitigate the risk related to the assertion. If the deficiency relates to one WCGW (what can go wrong) out of several WCGW’s, he can ‘rely on controls’ but performs additional substantive procedures to adequately address the risks related to the deficiency.","ours":{"approach":"Separate the cases: more than one control tested for the assertion (compensating controls may still support reliance), and the deficient control being the only one for the assertion.","difficulty":"hard"},"pg":{"q":"6","a":"3-4"},"note":"Ours: the January 2027 Study Material teaches the evaluation and reporting of control deficiencies (Risk Assessment and Internal Control: assess and report audit findings) but not the 'rely on controls' / 'not rely on controls' revision of ICAI's answer; the topic is in the syllabus, so the item is tagged, not flagged.","tags":["aud.risk.testing","aud.risk.ic"]},{"id":"o-p6-mtp-may2023-s1-q3b","section":"II","no":3,"marks":3,"type":"DESC","stem":"The auditor shall make a report to the members of the company on the accounts examined by him. Explain with reference to relevant provisions of the Companies Act, 2013.","label":"Q3(b)","part":"(b)","ord":33,"ans":"**Right to report to the members of the company on the accounts examined by him –** The auditor shall make a report to the members of the company on the accounts examined by him and on every financial statements which are required by or under this Act to be laid before the company in general meeting and the report shall after taking into account the provisions of this Act, the accounting and auditing standards and matters which are required to be included in the audit report under the provisions of this Act or any rules made there under or under any order made under this section and to the best of his information and knowledge, the said accounts, financial statements give a true and fair view of the state of the company’ s affairs as at the end of its financial year and profit or loss and cash flow for the year and such other matters as may be prescribed.","ours":{"difficulty":"easy"},"pg":{"q":"6","a":"4"},"tags":["aud.report.companies"]},{"id":"o-p6-mtp-may2023-s1-q3c","section":"II","no":3,"marks":3,"type":"DESC","stem":"Describe how risks in IT systems, if not mitigated, could have an impact on audit.","label":"Q3(c)","part":"(c)","ord":34,"ans":"When risks in IT systems are not mitigated the audit impact could be as follows:\n\n(i) The auditor may not be able rely on the reports, data obtained, automated controls, calculations and accounting procedures in the IT system.\n\n(ii) The auditor has to perform additional audit work by spending more time and efforts.\n\n(iii) The auditor may have to issue a modified opinion, if necessary.","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"4"},"tags":["aud.risk.it"]},{"id":"o-p6-mtp-may2023-s1-q3d","section":"II","no":3,"marks":4,"type":"DESC","stem":"“The role of audit committee in corporate governance is not limited to making recommendation for appointment of auditors only.” Discuss.","label":"Q3(d)","part":"(d)","ord":35,"ans":"Audit committee performs wide functions. The recommendation for appointment of auditors is only one of the several functions performed by audit committee. Under section 177 of companies Act, 2013, audit committee is responsible for following actions :-\n\n(i) the recommendation for appointment, remuneration and terms of appointment of auditors of the company;]\n\n(ii) review and monitor the auditor’s independence and performance, and effectiveness of audit process;\n\n(iii) examination of the financial statement and the auditors’ report thereon;\n\n(iv) approval or any subsequent modification of transactions of the company with related parties;\n\n(v) scrutiny of inter-corporate loans and investments;\n\n(vi) valuation of undertakings or assets of the company, wherever it is necessary;\n\n(vii) evaluation of internal financial controls and risk management systems;\n\n(viii) monitoring the end use of funds raised through public offers and related matters.\n\nHence, audit committee oversees range of matters including those related to making recommendation for appointment of auditors etc.","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"4"},"oos":true,"note":"Out of syllabus (old scheme, ours): the functions of the audit committee under section 177 of the Companies Act, 2013 belonged to old Paper 6's company audit chapter; the January 2027 Study Material mentions section 177 only in passing (the audit committee's evaluation of internal financial controls, fraud reporting to it) and does not teach the committee's functions, so the item is flagged and carries no tag (as in o-p6-pyq-jul2021). ICAI's answer prints \"the company;]\" in point (i); kept as printed."},{"id":"o-p6-mtp-may2023-s1-q4a","section":"II","no":4,"marks":4,"type":"DESC","stem":"Discuss the reporting requirements as per CARO, 2020, regarding:\n\n(i) disputed and undisputed statutory dues and\n\n(ii) internal audit system of the company","label":"Q4(a)","part":"(a)","ord":36,"ans":"Matters to be included as per CARO, 2020 :\n\n**Undisputed and Disputed Statutory dues**\n\nClause (vii)\n\n(a) whether the company is regular in depositing undisputed statutory dues including Goods and Services Tax, provident fund, employees' state insurance, income tax, sales-tax, service tax, duty of customs, duty of excise, value added tax, cess and any other statutory dues to the appropriate authorities and if not, the extent of the arrears of outstanding statutory dues as on the last day of the financial year concerned for a period of more than six months from the date they became payable, shall be indicated;\n\n(b) where statutory dues referred to in sub-clause (a) have not been deposited on account of any dispute, then the amounts involved and the forum where dispute is pending shall be mentioned (a mere representation to the concerned Department shall not be treated as a dispute).\n\n**Internal audit system**\n\nClause (xiv)\n\n(a) whether the company has an internal audit system commensurate with the size and nature of its business;\n\n(b) whether the reports of the Internal Auditors for the period under audit were considered by the statutory auditor.","ours":{"difficulty":"medium"},"pg":{"q":"7","a":"4-5"},"tags":["aud.report.caro"]},{"id":"o-p6-mtp-may2023-s1-q4b","section":"II","no":4,"marks":4,"type":"DESC","stem":"What are the required disclosures for cash & Cash equivalents to be made by the company as per Schedule III (Part I) to Companies Act, 2013?","label":"Q4(b)","part":"(b)","ord":37,"ans":"The following are the required disclosures for cash & Cash equivalents to be made by the company as per Schedule III (Part I) to Companies Act, 2013:\n\n**Cash and cash equivalents**\n\n(i) Cash and cash equivalents shall be classified as:\n\n(a) Balances with banks;\n\n(b) Cheques, drafts on hand;\n\n(c) Cash on hand;\n\n(d) Others (specify nature)\n\n(ii) Earmarked balances with banks (for example, for unpaid dividend) shall be separately stated.\n\n(iii) Balances with banks to the extent held as margin money or security against the borrowings, guarantees, other commitments shall be disclosed separately.\n\n(iv) Repatriation restrictions, if any, in respect of cash and bank balances shall be separately stated.\n\n(v) Bank deposits with more than 12 months’ maturity shall be disclosed separately.","ours":{"difficulty":"medium"},"pg":{"q":"7","a":"5"},"tags":["aud.items.current"]},{"id":"o-p6-mtp-may2023-s1-q4c","section":"II","no":4,"marks":6,"type":"DESC","stem":"Studymate Limited is a company engaged in the manufacture of stationery items. The company sells its goods on credit. The debtors as on 31.03.2022, amounted to ₹ 10 crores. What is the disclosure requirement for the company with respect to the ageing schedule of the trade receivables in terms of Schedule III (Part I) to the Companies Act, 2013?","label":"Q4(c)","part":"(c)","ord":38,"ans":"The following is the disclosure requirement for Studymate Limited with respect to the ageing schedule of the trade receivables in terms of Schedule III (Part I) to the Companies Act, 2013\n\nTrade Receivables ageing schedule\n\n(Amount in ₹)\n\n| Particulars | Outstanding for following periods from due date of payment# | | | | | |\n|---|---|---|---|---|---|---|\n| | **Less than 6 months** | **6 months-1 year** | **1-2 years** | **2-3 years** | **More than 3 years** | **Total** |\n| (i) Undisputed Trade receivables – considered good | | | | | | |\n| (ii) Undisputed Trade Receivables – considered doubtful | | | | | | |\n| (iii) Disputed Trade Receivables considered good | | | | | | |\n| (iv) Disputed Trade Receivables considered doubtful | | | | | | |\n\n\\# similar information shall be given where no due date of payment is specified, in that case disclosure shall be from the date of the transaction.\n\nUnbilled dues shall be disclosed separately.","ours":{"difficulty":"medium"},"pg":{"q":"7","a":"5-6"},"note":"Ours: ICAI's table prints \"(Amount in ₹)\" in a top row of empty cells, over the last two columns; it is written as a line above the table. The two-level header (Outstanding for following periods from due date of payment#, then the five periods and Total) follows the guide's merged-header rule.","tags":["aud.items.current"]},{"id":"o-p6-mtp-may2023-s1-q5a","section":"II","no":5,"marks":3,"type":"DESC","stem":"Akash & Associates are the statutory auditors of Deluxe Ltd. for the FY 2020-21. During the course of audit, CA Akash, the engagement partner requested the management of the company to provide written representation with respect to valuation of a transaction. The management, however does not provide the same to CA Akash. What course of action should CA Akash follow in such situation?","label":"Q5(a)","part":"(a)","ord":39,"ans":"If management of Deluxe Ltd. does not provide one or more of the requested written representations, CA Akash should:\n\n(a) Discuss the matter with management;\n\n(b) Re-evaluate the integrity of management and evaluate the effect that this may have on the reliability of representations (oral or written) and audit evidence in general; and\n\n(c) Take appropriate actions, including determining the possible effect on the opinion in the auditor’s report in accordance with SA 705.","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"6"},"tags":["aud.complete.sa580"]},{"id":"o-p6-mtp-may2023-s1-q5b","section":"II","no":5,"marks":4,"type":"DESC","stem":"\"An auditor is required to make specific evaluations while forming an opinion in an audit report.\" State those evaluations.","label":"Q5(b)","part":"(b)","ord":40,"ans":"**Specific Evaluations by the auditor:** In particular, the auditor shall evaluate whether :\n\n(i) The financial statements adequately disclose the significant accounting policies selected and applied;\n\n(ii) The accounting policies selected and applied are consistent with the applicable financial reporting framework and are appropriate;\n\n(iii) The accounting estimates made by management are reasonable;\n\n(iv) The information presented in the financial statements is relevant, reliable, comparable, and understandable;\n\n(v) The financial statements provide adequate disclosures to enable the intended users to understand the effect of material transactions and events on the information conveyed in the financial statements; and\n\n(vi) The terminology used in the financial statements, including the title of each financial statement, is appropriate.","ours":{"difficulty":"medium"},"pg":{"q":"7","a":"6"},"tags":["aud.report.sa700"]},{"id":"o-p6-mtp-may2023-s1-q5c-i","section":"II","no":5,"marks":4,"type":"DESC","stem":"Inventories","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c5","label":"Question 5(c)","context":"Explain and also state the role of auditor with respect to the following in case of a hotel:"},"label":"Q5(c)(i)","part":"(c)(i)","ord":41,"ans":"**Inventories**\n\nThe inventories in any hotel are both readily portable and saleable particularly the food and beverage inventories. It is therefore extremely important that all movements and transfers of such inventories should be properly documented to enable control to be exercised over each individual stores areas and sales point. The auditor should carry out tests to ensure that all such documentation is accurately processed.\n\nAreas where large quantities of inventory are held should be kept locked, the key being retained by the departmental manager. The key should be released only to trusted personnel and unauthorised persons should not be permitted in the stores areas except under constant supervision. In particular, any movement of goods in or out of the stores should be checked. Many hotels use specialised professional valuers to take and value the inventories on a continuous basis throughout the year. Such a valuation is then almost invariably used as the basis of the balance sheet inventory figure at the year end. Although such valuers are independent of the audit client, it is important that the auditor satisfies himself that the amounts included for such inventories are reasonable. In order to satisfy himself of this, the auditor should consider attending the physical inventory taking and carrying out certain pricing and calculation tests. The extent of such tests could well be limited since the figures will have been prepared independently of the hotel.","ours":{"difficulty":"medium"},"pg":{"q":"7","a":"6-7"},"case":"o-p6-mtp-may2023-s1-c5","tags":["aud.entities.institutions"]},{"id":"o-p6-mtp-may2023-s1-q5c-ii","section":"II","no":5,"marks":3,"type":"DESC","stem":"Travel agents & shops","group":{"kind":"case","id":"o-p6-mtp-may2023-s1-c5","label":"Question 5(c)","context":"Explain and also state the role of auditor with respect to the following in case of a hotel:"},"label":"Q5(c)(ii)","part":"(c)(ii)","ord":42,"ans":"**Travel agents & shops:**\n\n(i) For ledgers coming through travel agents or other booking agencies the bills are usually made on the travel agents or booking agencies. The auditor should ensure that money are recovered from the travel agents or booking agencies as per the terms of credit allowed.\n\n(ii) Commission, if any, paid to travel agents or booking agents should be checked by reference to the agreement on that behalf.","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"7"},"case":"o-p6-mtp-may2023-s1-c5","tags":["aud.entities.institutions"]},{"id":"o-p6-mtp-may2023-s1-q6a","section":"II","no":6,"marks":4,"type":"DESC","stem":"When are following considered as non performing as per the RBI guidelines?\n\n(i) Government guaranteed advances\n\n(ii) Advances to staff","label":"Q6(a)","part":"(a)","ord":43,"ans":"**Government Guaranteed advances:**\n\n- Central Govt. guaranteed Advances, where the guarantee is not invoked/ repudiated would be classified as Standard Assets, but regarded as NPA for Income Recognition purpose.\n- The situation would be different if the advance is guaranteed by State Government, where advance is to be considered NPA if it remains overdue for more than 90 days for both Provisioning and Income recognition purposes.\n\n**Advances to Staff**\n\nInterest-bearing staff advances as a banker should be included as part of advances portfolio of the bank. In the case of housing loan or similar advances granted to staff members where interest is payable after recovery of principal, interest need not be considered as overdue from the first quarter onwards. Such loans/advances should be classified as NPA only when there is a default in repayment of installment of principal or payment of interest on the respective due dates. The staff advances by a bank as an employer and not as a banker are required to be included under the sub-head ‘Others’ under the schedule of Other Assets.","ours":{"difficulty":"medium"},"pg":{"q":"7","a":"7"},"tags":["aud.bank.advances"]},{"id":"o-p6-mtp-may2023-s1-q6b","section":"II","no":6,"marks":4,"type":"DESC","stem":"Explain pledge and set off as the modes of creation of security with respect to advance granted by a bank.","label":"Q6(b)","part":"(b)","ord":44,"ans":"**Pledge:** A pledge involves bailment or delivery of goods by the borrower to the lending bank with the intention of creating a charge thereon as security for the advance. The legal ownership of the goods remains with the pledger while the lending banker gets certain defined interests in the goods. The pledge of goods constitutes a specific (or fixed) charge.\n\n**Set-off:** Set-off is a statutory right of a creditor to adjust, wholly or partly, the debit balance in the debtor’s account against any credit balance lying in another account of the debtor. The right of set-off enables a bank to combine two accounts (a deposit account and a loan account) of the same person provided both the accounts are in the same name and same right (i.e., the capacity of the account holder in both the accounts should be the same).\n\nFor the purpose of set-off, all the branches of a bank are treated as one single entity. The right of set-off can be exercised in respect of time-barred debts also.","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"7"},"tags":["aud.bank.advances"]},{"id":"o-p6-mtp-may2023-s1-q6c","section":"II","no":6,"marks":4,"type":"DESC","stem":"State the points which merit consideration in the audit of a CLUB w.r.t its members.","label":"Q6(c)","part":"(c)","ord":45,"ans":"**The points which merit consideration in the audit of a CLUB w.r.t its members:**\n\n(1) **Entrance Fee:** Vouch the receipt on account of ***entrance fees*** with –\n\n- members’ applications and counterfoils issued to them,\n- on a reference to minutes of the Managing Committee.\n\n(2) **Member Subscriptions:** Vouch members’ subscriptions with –\n\n- the counterfoils of receipt issued to them,\n- trace receipts for a selected period to the Register of Members;\n- also reconcile the amount of total subscriptions due with the amount collected and that outstanding.\n\n(3) **Subscription Arrears/in Advance:** Ensure that –\n\n- **arrears** of subscriptions for the previous year have been correctly brought over,\n- **arrears** for the year under audit and subscriptions received in advance have been correctly adjusted.\n- Subscriptions received in advance should have been properly accounted for.\n\n(4) **Arithmetical accuracy:** Check totals of various columns of the Register of members and tally them across.\n\n(5) **Register of Members:** See the ***Register of Members*** to ascertain –\n\n- the Member’s dues which are in arrear and\n- enquire whether necessary steps have been taken for their recovery;\n- the amount considered irrecoverable should be mentioned in the Audit Report.\n\n(6) **Member Accounts :-** Trace debits for a selected period from subsidiary registers maintained in respect of supplies and services to members to confirm that the account of every member has been debited with amounts recoverable from him.","ours":{"difficulty":"medium"},"pg":{"q":"7","a":"7-8"},"alt":"o-p6-mtp-may2023-s1-q6b","note":"Ours: ICAI prints \"OR\" between Q6(b) and Q6(c), so (c) is the alternative to (b) and Q6 carries 4 + 4 + 3 + 3 = 14 marks like Q2-Q5.","tags":["aud.entities.institutions"]},{"id":"o-p6-mtp-may2023-s1-q6d","section":"II","no":6,"marks":3,"type":"DESC","stem":"While verifying the legal and professional expenses of the client company, what audit procedures should the auditor perform?","label":"Q6(d)","part":"(d)","ord":46,"ans":"While verifying the legal and professional expenses of the client company, the auditor should perform the following audit procedures\n\n- Obtain a month-wise and consultant-wise summary.\n- In case of monthly retainership agreements, verify whether the expenditure for all 12 months has been recorded correctly.\n- For non- recurring expenses, select a sample and vouch for the attributes discussed above.\n- The auditor should be cautious while vouching for legal expenses as the same may highlight a dispute for which the entity may not have made any provision and the matter may also not have been discussed/ highlighted to the auditor for his specific consideration.","ours":{"difficulty":"medium"},"pg":{"q":"7","a":"8"},"note":"ICAI's answer prints \"For non- recurring expenses\" and \"vouch for the attributes discussed above\" (no attributes are discussed in the answer); kept as printed.","tags":["aud.items.expenses"]},{"id":"o-p6-mtp-may2023-s1-q6e","section":"II","no":6,"marks":3,"type":"DESC","stem":"Name the assertion that the auditor will check by performing the following audit procedures.\n\n(a) Employees benefit expense in respect of all personnel have been fully accounted for.\n\n(b) Discounts on sales has been properly adjusted/ accounted for.\n\n(c) Employee benefit expense recorded during the period relates to the current accounting period only.","label":"Q6(e)","part":"(e)","ord":47,"ans":"a) Completeness\n\nb) Measurement\n\nc) Cut Off","ours":{"difficulty":"easy"},"pg":{"q":"7","a":"8"},"tags":["aud.evid.assertions","aud.items.expenses"]}]);
